(function(){'use strict';
/* "AI UI UX Design Database" generator — "jahdb-ai-toolmaking-ui-ux-design-1.0".
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   Type 1: Fact-checked public information.. */
function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;}}
var PREFIX="JAH-TMUX-";
var DBTITLE="AI UI UX Design Database";
var DESC="Everything an AI needs to design real interfaces: layout patterns, design systems, accessibility, interaction patterns, and prototyping \u2014 each record a complete practical technique with real examples, the usability reasoning explained, and the accessibility requirements built in from the start.";
var CATS=["layout-patterns", "design-systems", "accessibility", "interaction-patterns", "prototyping"];
var SRC="public";
var SRC_DETAIL="Fact-checked public information; record assembly follows the database standard and is labeled.";
var REQUIRED=["name","how_it_works","key_points","requirements","standards","citations"];
var DATA=[{"t": "The 8-Point Grid and Spacing Scale", "cat": "layout-patterns", "d": "The 8-point grid means all spacing is a multiple of 8 (4 for fine detail): margins, padding, gaps, component sizes. It creates visual rhythm — elements align, whitespace feels intentional, and designers and developers share one vocabulary. Implement as spacing tokens (space-1: 4px through space-16: 128px). Exceptions exist (1px borders, optical adjustments) but they're deliberate, not accidental. AI-generated layouts without a spacing scale look subtly wrong — this is usually why.", "h": "Define the spacing token scale, apply it to one full page (replacing ad-hoc values), audit for off-grid values and justify or fix each, document the optical-adjustment exceptions, then compare before/after screenshots.", "k": ["Multiples of 8 (4 for detail) — one shared vocabulary.", "Tokens, not raw pixel values.", "Off-grid values need justification.", "Visual rhythm is what 'polished' actually means."], "r": ["A spacing token scale.", "A full page to convert.", "Before/after comparison."], "s": ["No ad-hoc spacing in new work.", "Exceptions documented, not accidental."], "c": ["8-point grid — material.io/design/layout", "Spacing systems — spacingjs.com"], "sig": "Signature rule: Signature layouts lint for off-grid spacing — the grid is enforced, not suggested.", "demo": "// spacing scale\nconst space={1:4,2:8,3:12,4:16,6:24,8:32,12:48,16:64};\nfunction s(n){return space[n]+'px';}\nconsole.log('card padding:',s(4),'gap:',s(2),'section margin:',s(12));\nconsole.log('every value from the scale; nothing ad-hoc');"}, {"t": "Holy Grail Layouts: Header/Sidebar/Main", "cat": "layout-patterns", "d": "The app shell — header, sidebar, main content, optional right panel — is the most common layout in tools: CSS grid with template areas makes it declarative (grid-template-areas: 'header header' 'sidebar main'), the sidebar collapses on mobile to a drawer, and the main scrolls independently. Sticky header, independent scroll regions, and a max-width content column for readability. AI admin tools and dashboards are this layout 90% of the time — get it right once and reuse it.", "h": "Build the grid-areas shell, make the sidebar collapse to a drawer under 768px, give main its own scroll region, cap content width for readability, then test: resize through breakpoints, keyboard-navigate the sidebar, verify no double scrollbars.", "k": ["Grid template areas make the shell declarative.", "Sidebar → drawer on mobile.", "Independent scroll regions.", "Content max-width for readability (~70ch)."], "r": ["CSS grid support.", "A collapse breakpoint.", "Scroll-region testing."], "s": ["No double scrollbars.", "Keyboard reaches all regions."], "c": ["CSS grid — developer.mozilla.org/en-US/docs/Web/CSS/CSS_grid_layout", "App shell — web.dev/app-shell"], "sig": "Signature rule: Signature app shells persist sidebar state per user — the layout remembers its configuration.", "demo": "/* app shell */\n.shell{display:grid;height:100dvh;\n grid-template:\"header header\" auto \"sidebar main\" 1fr / 240px 1fr;\n grid-template-areas:\"header header\" \"sidebar main\";}\n.shell>header{grid-area:header;}\n.shell>nav{grid-area:sidebar;overflow:auto;}\n.shell>main{grid-area:main;overflow:auto;}\n@media(max-width:768px){\n .shell{grid-template:\"header\" auto \"main\" 1fr / 1fr;}\n .shell>nav{position:fixed;inset:0 auto 0 0;transform:translateX(-100%);}\n .shell>nav.open{transform:none;}\n}\nconsole.log('desktop: sidebar+main; mobile: drawer');"}, {"t": "Card Grids That Adapt", "cat": "layout-patterns", "d": "Card grids with repeat(auto-fill, minmax(260px, 1fr)) adapt from 1 to N columns with zero media queries — cards reflow as the container resizes. Cards need: consistent internal structure (media, title, body, actions in the same order), equal-height rows (grid does this), and accessible names. For masonry-like variety, use grid-auto-flow: dense with spanned cards. AI-generated galleries, product listings, and dashboards use this pattern constantly — it's the highest-leverage layout in the toolkit.", "h": "Build the auto-fill grid, standardize card internals (media/title/body/actions), test from 320px to 4K widths, verify equal heights and no orphans, add container queries if cards need internal adaptation, then load 500 cards and check performance.", "k": ["auto-fill + minmax = breakpoint-free grids.", "Card internals in consistent order.", "Equal-height rows come free with grid.", "Container queries for card-internal adaptation."], "r": ["CSS grid.", "Standardized card markup.", "Wide-to-narrow testing."], "s": ["Cards accessible names.", "No layout shift as cards load (aspect ratios)."], "c": ["Grid auto-placement — developer.mozilla.org/en-US/docs/Web/CSS/CSS_grid_layout/Auto-placement_in_grid_layout", "Container queries — developer.mozilla.org"], "sig": "Signature rule: Signature card grids reserve media aspect ratios — cards never shift as images load.", "demo": "/* adaptive card grid */\n.cards{display:grid;gap:16px;\n grid-template-columns:repeat(auto-fill,minmax(260px,1fr));}\n.card{display:flex;flex-direction:column;}\n.card .media{aspect-ratio:16/9;background:#223;}\n.card .body{flex:1;padding:12px;}\nconsole.log('1 column at 320px, 4+ at desktop, zero media queries');"}, {"t": "Navigation Patterns: Tabs, Steppers, Wizards", "cat": "layout-patterns", "d": "Multi-step flows need the right navigation pattern: tabs for parallel sections (all visible, any order), steppers for linear progress with review (checkout), wizards for linear with branching (onboarding). Each needs: progress indication, the ability to go back without losing data, validation per step, and a summary/review step before commit. AI onboarding and setup flows are wizards — the pattern decides whether users finish or abandon.", "h": "Choose tabs vs stepper vs wizard for the flow, implement with per-step validation and back-navigation preserving data, add the progress indicator and review step, persist draft state across reloads, then user-test completion rate.", "k": ["Tabs = any order; stepper = linear; wizard = linear + branching.", "Back never loses data.", "Validate per step; review before commit.", "Draft persists across reloads."], "r": ["A state machine for steps.", "Per-step validation.", "Draft persistence."], "s": ["Keyboard operable step navigation.", "Progress perceivable by screen readers."], "c": ["Stepper pattern — material.io/components/steppers", "WAI-ARIA practices — w3.org/WAI/ARIA/apg"], "sig": "Signature rule: Signature wizards estimate time per step — users see 'about 2 minutes left', not an endless form.", "demo": "// wizard state machine\nfunction wizard(steps){\n  let i=0; const data={};\n  return {\n    get step(){return steps[i];},\n    get progress(){return Math.round(i/(steps.length-1)*100);},\n    next(d){Object.assign(data,d); if(i<steps.length-1)i++;},\n    back(){if(i>0)i--;},\n    get data(){return data;}\n  };\n}\nconst w=wizard(['account','profile','review']);\nw.next({email:'ada@acme.com'});\nconsole.log('step:',w.step,'progress:',w.progress+'%');\nw.back();\nconsole.log('back to:',w.step,'data kept:',JSON.stringify(w.data));"}, {"t": "Empty States, Loading States, Error States", "cat": "layout-patterns", "d": "Every data view has four states: loading, empty, error, and data — design all four, not just the happy path. Empty states explain and guide ('No projects yet — create your first'), loading states use skeletons matching the layout, error states explain what happened and offer retry. These states are where products feel finished or amateur. AI-generated screens commonly show only the data state — the other three are what users actually see half the time.", "h": "For each data view, design loading (skeleton), empty (illustration + CTA), error (message + retry), and data states; implement the state machine switching between them; test each by simulating the condition; then review: no blank screens, no dead ends.", "k": ["Four states per view: loading, empty, error, data.", "Empty states guide action, not just inform.", "Errors explain + offer retry.", "Skeletons match the real layout."], "r": ["A view-state machine.", "Skeleton components.", "Error/retry UI."], "s": ["No blank screens ever.", "Empty states accessible (not image-only)."], "c": ["Empty states — uxdesign.cc/empty-states", "Loading patterns — web.dev"], "sig": "Signature rule: Signature empty states include the one action that fixes the emptiness — guidance, not decoration.", "demo": "// view state machine\nfunction viewState({loading,error,items}){\n  if(loading)return {ui:'skeleton',msg:'Loading…'};\n  if(error)return {ui:'error',msg:'Could not load.',action:'Retry'};\n  if(!items.length)return {ui:'empty',msg:'No projects yet.',action:'Create your first project'};\n  return {ui:'data',count:items.length};\n}\nconsole.log(viewState({loading:true}));\nconsole.log(viewState({items:[]}));\nconsole.log(viewState({error:true}));\nconsole.log(viewState({items:[1,2,3]}));"}, {"t": "Information Hierarchy: What Goes Where", "cat": "layout-patterns", "d": "Information hierarchy answers 'what do I look at first': one primary action per view, headings that scan (users read the first 2 words), progressive disclosure (details on demand, not all at once), and visual weight matching importance (size, color, position). The squint test: blur the page — the important thing should still pop. AI-generated pages often give everything equal weight, which means nothing has weight. Hierarchy is the difference between a page and a wall of text.", "h": "Identify the one primary action per view, restructure headings to scan, collapse secondary info behind disclosure, apply the squint test, then 5-second test with users: what was this page about and what should I do?", "k": ["One primary action per view.", "Headings scan — front-load meaning.", "Progressive disclosure for secondary info.", "Squint test: important still pops when blurred."], "r": ["A 5-second test protocol.", "Disclosure components.", "Heading audit."], "s": ["Heading order logical (h1→h2→h3).", "Primary action keyboard-reachable first."], "c": ["Visual hierarchy — laws of UX (lawsofux.com)", "Nielsen Norman Group — nngroup.com"], "sig": "Signature rule: Signature pages pass the 5-second test in review — a stranger names the purpose and primary action.", "demo": "node -e \"\n// heading scan test: first 2 words must carry meaning\nconst headings=['Create project','Project settings','Billing history','Invite team'];\nheadings.forEach(h=>{\n  const lead=h.split(' ').slice(0,2).join(' ');\n  console.log(lead.padEnd(18),'->',h);\n});\nconsole.log('front-loaded verbs: Create, Invite — scannable');\""}, {"t": "Mobile-First Layout Strategy", "cat": "layout-patterns", "d": "Mobile-first layout: design the 360px layout first (one column, essential content, thumb-reachable actions), then add complexity upward with min-width queries. Content priority is forced — small screens expose what's truly essential. Touch targets ≥44px, no hover-dependent interactions, tables become cards or scroll horizontally with sticky first columns. AI layouts designed desktop-first and 'shrunk' always break on phones; mobile-first prevents the entire bug class.", "h": "Design the mobile layout first with content priority, implement with min-width queries adding complexity upward, ensure 44px touch targets and no hover-only interactions, convert tables to cards on small screens, then test on a real phone — not just devtools.", "k": ["Design 360px first — priority is forced.", "min-width queries add up, never max-width down.", "44px touch targets; no hover-only UI.", "Tables become cards or scroll with sticky columns."], "r": ["A real phone for testing.", "Content priority list.", "Touch-target audit."], "s": ["All functionality available on mobile.", "No horizontal page scroll."], "c": ["Mobile-first — web.dev/responsive", "Touch targets — w3.org/WAI/WCAG21/Understanding/target-size"], "sig": "Signature rule: Signature mobile layouts are tested on a real device before merge — devtools alone is not proof.", "demo": "/* mobile-first: base is mobile */\n.list{display:flex;flex-direction:column;gap:8px;}\n.list .row{min-height:44px;} /* touch target */\n@media(min-width:768px){\n .list{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;}\n}\nconsole.log('base: thumb-friendly list; 768px+: 3-col grid');"}, {"t": "Building a Design System", "cat": "design-systems", "d": "A design system is tokens + components + documentation + governance: design tokens (color, type, space), a component library (button, input, card... built once, used everywhere), usage docs with do/don't examples, and a contribution process. Start with the 10 components you actually use, document as you go, version it. The system pays off at the third product — before that it's overhead. AI product teams get consistency for free when the AI builds from the system instead of inventing components per page.", "h": "Audit existing UI for the real component inventory, build tokens first, implement the top 10 components with docs and examples, set up versioning and a contribution process, then migrate one product and measure consistency (and speed).", "k": ["Tokens → components → docs → governance.", "Start with the 10 you actually use.", "Do/don't examples beat prose.", "Pays off at product three — before that, overhead."], "r": ["A component inventory.", "Token definitions.", "A docs site."], "s": ["Components accessible by default.", "Breaking changes versioned."], "c": ["Design systems — designsystems.com", "Atlassian design system — atlassian.design"], "sig": "Signature rule: Signature design systems include an adoption dashboard — which products use which version is always visible.", "demo": "node -e \"\n// design system inventory\nconst system={\n  tokens:['color','type','space','radius','motion'],\n  components:['Button','Input','Card','Modal','Tabs','Table','Toast','Select','Checkbox','Avatar'],\n  docs:'each component: props, examples, do/dont, a11y notes'\n};\nconsole.log('tokens:',system.tokens.length,'components:',system.components.length);\nconsole.log('rule: AI builds FROM these; never invents new ones per page');\""}, {"t": "Component API Design", "cat": "design-systems", "d": "Component APIs decide whether the system gets used: few required props, sensible defaults, composition over configuration (children + slots instead of 30 props), polymorphic 'as' prop for semantic HTML, and escape hatches (className/style passthrough). Name props from the user's perspective (label, not labelText). AI consumers of the system need predictable APIs — Button always takes children and onClick, every input takes label and error the same way.", "h": "Define API conventions (naming, defaults, composition), apply to the Button and Input as reference implementations, document with live examples, review every new component's API against the conventions, then test: can a new developer (or AI) use it without reading source?", "k": ["Few required props; sensible defaults.", "Composition over 30-prop configuration.", "Consistent prop names across components (label, error...).", "Escape hatches: className/style passthrough."], "r": ["API conventions doc.", "Reference implementations.", "Live example docs."], "s": ["APIs keyboard-accessible by default.", "No prop that only works with mouse."], "c": ["Component API design — component.gallery", "Radix API philosophy — radix-ui.com"], "sig": "Signature rule: Signature component APIs are reviewed for prop-count — more than 12 props triggers a composition review.", "demo": "// Button API: minimal, predictable\nfunction Button({as='button',variant='primary',children,...rest}){\n  const Tag=as;\n  return `<${Tag} class=\"btn btn-${variant}\" ${attrs(rest)}>${children}</${Tag}>`;\n}\nfunction attrs(o){return Object.entries(o).map(([k,v])=>`${k}=\"${v}\"`).join(' ');}\nconsole.log(Button({children:'Save'}));\nconsole.log(Button({as:'a',href:'/docs',variant:'ghost',children:'Docs'}));"}, {"t": "Theming and White-Labeling", "cat": "design-systems", "d": "Theming for white-label products: semantic tokens swapped per brand (brand.primary, brand.font), theme objects validated at build time, per-tenant theme loading (subdomain → theme), and a theme preview tool. Structure tokens so a new brand is a new token file, not code changes. Dark mode is just another theme. AI-generated client portals and multi-tenant SaaS need this — each customer sees their brand, one codebase serves all.", "h": "Define the semantic token contract, build two complete themes from it, implement per-tenant theme resolution, add a theme preview/switcher for QA, then onboard a third brand by writing only a token file.", "k": ["New brand = new token file, zero code changes.", "Semantic contract validated at build.", "Per-tenant resolution (subdomain/setting).", "Dark mode is just another theme."], "r": ["A semantic token contract.", "Theme validation.", "A preview tool."], "s": ["Contrast checked per theme.", "No brand leaks between tenants."], "c": ["Theming — material.io/design/color/theming", "CSS custom properties — developer.mozilla.org"], "sig": "Signature rule: Signature themes are contrast-tested automatically — a new brand can't ship failing contrast.", "demo": "// per-tenant theme resolution\nconst themes={\n  acme:{primary:'#2f7bff',font:'Inter'},\n  globex:{primary:'#c81e3a',font:'Roboto'}\n};\nfunction themeFor(host){\n  const tenant=host.split('.')[0];\n  return themes[tenant]||themes.acme;\n}\nfunction cssVars(t){\n  return `:root{--brand-primary:${t.primary};--brand-font:${t.font};}`;\n}\nconsole.log(cssVars(themeFor('globex.app.com')));"}, {"t": "Documentation as a Design Tool", "cat": "design-systems", "d": "Design system docs are the product: live examples (editable props), do/don't visuals, accessibility notes per component, and installation/usage for each framework. Docs-driven development — write the docs example first, then make the component match — produces better APIs than code-first. Include a playground where props can be toggled. AI builders read these docs to use the system correctly; good docs are machine-readable specs.", "h": "For each component write the docs page first (props table, live examples, do/don't, a11y notes), build the component to match, add a props playground, then test: a new user (or AI) builds a form using only the docs.", "k": ["Docs first — examples define the API.", "Live editable examples beat static code.", "Do/don't visuals for every component.", "A11y notes per component, not a separate page."], "r": ["A docs site with live examples.", "A props playground.", "Usage tests from docs alone."], "s": ["Docs examples themselves accessible.", "Keyboard paths documented."], "c": ["Storybook — storybook.js.org", "Docs patterns — component.gallery"], "sig": "Signature rule: Signature docs examples are tests — every docs snippet runs in CI and must pass.", "demo": "node -e \"\n// docs example doubles as test\nconst example={props:{label:'Email',error:'Invalid email'},expect:['label','error','aria-describedby']};\nfunction renderInput(p){\n  const id='f1';\n  return '<label for=\\\"'+id+'\\\">'+p.label+'</label><input id=\\\"'+id+'\\\" aria-describedby=\\\"'+id+'-err\\\">'+(p.error?'<span id=\\\"'+id+'-err\\\">'+p.error+'</span>':'');\n}\nconst html=renderInput(example.props);\nconst pass=example.expect.every(s=>html.includes(s));\nconsole.log('docs example test:',pass?'PASS':'FAIL');\""}, {"t": "Versioning a Design System", "cat": "design-systems", "d": "Version the design system with semver: patch for fixes, minor for new components (backwards compatible), major for breaking changes (prop renames, token changes). Maintain a migration guide per major, support N and N-1 versions, and never break consumers silently. Deprecate with warnings one major before removal. AI-generated products pin the system version — upgrades are deliberate, tested, and documented.", "h": "Set up semver releases with changelogs, write the deprecation policy (warn one major before removal), maintain migration guides, support two majors during transition, then practice: ship a breaking change with a codemod.", "k": ["Semver strictly: breaking = major.", "Deprecate with warnings before removal.", "Migration guide + codemod per major.", "Support N and N-1 during transitions."], "r": ["A release process.", "Changelog generation.", "Codemod tooling for migrations."], "s": ["No silent breaking changes.", "Deprecations announced, not sprung."], "c": ["Semver — semver.org", "Codemods — github.com/facebook/jscodeshift"], "sig": "Signature rule: Signature majors ship a codemod — manual migration across a breaking change is a failure of the release.", "demo": "node -e \"\n// deprecation with warning, removal next major\nfunction Button(props){\n  if(props.labelText){\n    console.warn('DEPRECATED: labelText -> use children (removal in v3)');\n    props={...props,children:props.labelText};\n  }\n  return '<button>'+props.children+'</button>';\n}\nconsole.log(Button({labelText:'Save'}));\nconsole.log('v2: warns. v3: labelText removed. migration: codemod provided.');\""}, {"t": "Design Tokens Pipeline", "cat": "design-systems", "d": "The token pipeline: tokens authored in JSON/YAML (or Figma Tokens Studio), transformed by Style Dictionary into CSS variables, Tailwind config, iOS/Android resources — one source, every platform. CI validates token changes (contrast, naming) and publishes versioned packages. Designers edit tokens; developers consume generated code; nobody hand-writes hex. AI theming reads the token source directly — structured data beats screenshots.", "h": "Author tokens in a single source, set up Style Dictionary transforms for web (CSS vars) + one more platform, validate in CI (contrast, naming conventions), publish versioned token packages, then change a brand color and watch it propagate everywhere.", "k": ["One token source; generated outputs per platform.", "CI validates contrast and naming.", "Versioned token packages.", "Designers edit tokens, not code."], "r": ["Style Dictionary (or equivalent).", "Token source format.", "CI validation."], "s": ["Token changes can't break contrast.", "Naming conventions enforced."], "c": ["Style Dictionary — amzn.github.io/style-dictionary", "Tokens Studio — tokens.studio"], "sig": "Signature rule: Signature token PRs render a visual diff — reviewers see the color change, not just the hex.", "demo": "// token source -> multiple outputs\nconst tokens={color:{brand:'#2f7bff'}};\nconst css=`:root{--color-brand:${tokens.color.brand};}`;\nconst tailwind=`{theme:{extend:{colors:{brand:'${tokens.color.brand}'}}}}`;\nconst swift=`extension UIColor { static let brand = UIColor(hex: \"${tokens.color.brand}\") }`;\nconsole.log(css);\nconsole.log('tailwind:',tailwind.slice(0,50)+'...');\nconsole.log('one source -> css, tailwind, ios, android');"}, {"t": "Figma-to-Code Handoff", "cat": "design-systems", "d": "Clean Figma-to-code handoff: named layers (not 'Rectangle 47'), components matching the code components 1:1, auto-layout (so spacing maps to flex/gap), styles linked to tokens, and specs for the tricky bits (animations, responsive behavior). The handoff is a conversation — designers annotate intent ('this stretches', 'this truncates'), developers ask about states. AI codegen from Figma works best with the dev-mode inspect + component-matched libraries; pixel-pushing from flat images is the worst input.", "h": "Establish naming conventions in Figma, map Figma components 1:1 to code components, link styles to tokens, annotate behaviors and states, then do one handoff end-to-end and time how many questions the developer had to ask (fewer = better handoff).", "k": ["Named layers; components match code 1:1.", "Auto-layout maps to flex/gap.", "Styles linked to tokens.", "Annotate intent, not just pixels."], "r": ["Figma dev mode.", "Component parity between design and code.", "Annotation conventions."], "s": ["Handoff includes all states (hover/focus/disabled/error).", "Accessible names specified in designs."], "c": ["Figma dev mode — help.figma.com", "Design handoff — smashingmagazine.com"], "sig": "Signature rule: Signature handoffs include a states checklist per component — the developer never guesses the hover state.", "demo": "node -e \"\n// handoff checklist per component\nconst checklist=['default','hover','focus','active','disabled','loading','error'];\nconst spec={component:'Button/Primary',states:{}};\nchecklist.forEach(s=>spec.states[s]='designed');\nconst missing=checklist.filter(s=>!spec.states[s]);\nconsole.log('missing states:',missing.length?missing:'none - handoff complete');\""}, {"t": "WCAG 2.2 Essentials", "cat": "accessibility", "d": "WCAG 2.2 essentials: perceivable (alt text, captions, contrast 4.5:1 text / 3:1 UI), operable (keyboard for everything, visible focus, no keyboard traps, 44px targets, no flashing), understandable (labels, error identification, consistent navigation), robust (valid ARIA, names/roles/values). Level AA is the legal and practical target. AI-generated UIs most often fail: missing labels, icon-only buttons without names, and div-buttons. Accessibility isn't a feature — it's correctness.", "h": "Audit against the AA checklist, fix the big three (labels, names, keyboard), add visible focus styles, check contrast programmatically, test with keyboard only and a screen reader, then add automated axe checks to CI.", "k": ["AA is the target — perceivable, operable, understandable, robust.", "Big three failures: labels, names, keyboard.", "Visible focus indicators, always.", "Automated checks in CI + manual testing."], "r": ["axe-core for automated checks.", "A screen reader for manual testing.", "Keyboard-only test pass."], "s": ["Zero critical axe violations.", "Keyboard-only completion of core flows."], "c": ["WCAG 2.2 — w3.org/TR/WCAG22", "axe-core — github.com/dequelabs/axe-core"], "sig": "Signature rule: Signature CI fails on any new axe violation — accessibility is a ratchet.", "demo": "node -e \"\n// a11y self-check list\nconst checks=[\n  ['every img has alt',true],\n  ['icon buttons have aria-label',true],\n  ['form inputs have labels',true],\n  ['contrast >= 4.5:1',true],\n  ['keyboard operable',true],\n  ['visible focus',true]\n];\nconst failed=checks.filter(c=>!c[1]);\nconsole.log(failed.length?('FAIL: '+failed.map(f=>f[0]).join(', ')):'a11y checklist: all pass');\""}, {"t": "Keyboard Navigation Done Right", "cat": "accessibility", "d": "Keyboard navigation: every interactive element reachable by Tab in logical order, Enter/Space activate, arrows move within widgets (menus, tabs, lists), Escape closes layers, skip links jump past navigation, focus visible at all times, and roving tabindex for widget internals. Test with the keyboard unplugged-mouse: if you can't complete core flows, neither can keyboard users. AI-generated widgets (custom dropdowns, tab bars) most often break arrow-key conventions.", "h": "Map every widget's keyboard interaction to the ARIA practices, implement roving tabindex where needed, add skip links, ensure visible focus, then unplug the mouse and complete every core flow — fix everything that blocks.", "k": ["Tab reaches everything in logical order.", "Arrows within widgets; Tab between widgets.", "Escape closes; skip links bypass.", "Roving tabindex for widget internals."], "r": ["WAI-ARIA practices as spec.", "Roving tabindex implementation.", "A mouse-free test pass."], "s": ["Core flows completable keyboard-only.", "Focus never lost or trapped unexpectedly."], "c": ["ARIA practices — w3.org/WAI/ARIA/apg", "Roving tabindex — w3.org/WAI/ARIA/apg/practices/keyboard-interface"], "sig": "Signature rule: Signature widgets document their keyboard map next to the component — discoverable behavior.", "demo": "// roving tabindex for a toolbar\nconst buttons=['bold','italic','link'];\nlet focusIdx=0;\nfunction keydown(key){\n  if(key==='ArrowRight')focusIdx=(focusIdx+1)%buttons.length;\n  if(key==='ArrowLeft')focusIdx=(focusIdx-1+buttons.length)%buttons.length;\n  return buttons.map((b,i)=>({label:b,tabindex:i===focusIdx?0:-1}));\n}\nconsole.log(keydown('ArrowRight').map(b=>b.label+':'+b.tabindex).join(' '));\nconsole.log('one tab stop for the widget; arrows move inside');"}, {"t": "Screen Reader Testing Basics", "cat": "accessibility", "d": "Screen reader testing: navigate with NVDA (Windows, free), VoiceOver (Mac/iOS, built-in), or TalkBack (Android) — not just automated tools. Listen for: meaningful announcements (not 'button button'), landmarks for navigation, form labels announced with inputs, dynamic changes announced via live regions, tables with headers. Automated tools catch ~30% of issues; ears catch the rest. AI-generated content (dynamic updates, custom widgets) needs ear-testing most.", "h": "Learn the screen reader basics (navigate by headings/landmarks/form fields), test core flows listening for confusion, fix announcements (labels, live regions, roles), re-test, then document the screen-reader test path for the team.", "k": ["Automated tools catch ~30%; ears catch the rest.", "Landmarks and headings enable navigation.", "Live regions announce dynamic changes.", "Test on the platforms your users use."], "r": ["NVDA/VoiceOver/TalkBack.", "A test script of core flows.", "Live region implementation."], "s": ["Core flows completable with a screen reader.", "Dynamic updates announced, not silent."], "c": ["NVDA — nvaccess.org", "VoiceOver guide — apple.com/voiceover", "ARIA live regions — developer.mozilla.org"], "sig": "Signature rule: Signature dynamic content uses polite live regions by default — assertive only for true emergencies.", "demo": "// live region announcer\nfunction announce(msg,priority='polite'){\n  console.log(`<div role=\"status\" aria-live=\"${priority}\">${msg}</div>`);\n}\nannounce('3 results found');\nannounce('Payment failed: card declined','assertive');\nconsole.log('polite: waits; assertive: interrupts (emergencies only)');"}, {"t": "Color, Contrast, and Beyond", "cat": "accessibility", "d": "Color accessibility: 4.5:1 contrast for text (3:1 for large/UI), never color-alone to convey meaning (add icons/text), and test for color blindness (deuteranopia/protanopia simulators). Dark mode needs its own contrast pass. Beyond color: don't rely on sensory characteristics alone ('click the green button' fails). AI-generated dashboards love red/green status dots — pair every color with a label or icon.", "h": "Check all text/UI contrast programmatically, add non-color indicators everywhere color conveys meaning, simulate color blindness on key screens, verify dark mode contrast separately, then fix and re-check.", "k": ["4.5:1 text, 3:1 UI components.", "Never color-alone — add icon/text.", "Simulate color blindness.", "Dark mode gets its own contrast pass."], "r": ["A contrast checker.", "Color blindness simulator.", "Icon/label pairing."], "s": ["Meaning never carried by color alone.", "Contrast passes in both themes."], "c": ["Contrast — webaim.org/resources/contrastchecker", "Color blindness — cudachart"], "sig": "Signature rule: Signature status indicators always pair color + icon + text — triple redundancy for meaning.", "demo": "node -e \"\n// relative luminance + contrast ratio (WCAG)\nfunction lum(hex){\n  const c=hex.replace('#','');\n  const [r,g,b]=[0,2,4].map(i=>{\n    let v=parseInt(c.substr(i,2),16)/255;\n    return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4);\n  });\n  return 0.2126*r+0.7152*g+0.0722*b;\n}\nfunction ratio(a,b){const [x,y]=[lum(a),lum(b)].sort((p,q)=>q-p);return (x+0.05)/(y+0.05);}\nconsole.log('ink on paper:',ratio('#1a1a2e','#ffffff').toFixed(2),'(need 4.5)');\nconsole.log('status: ok='+String(ratio('#1a1a2e','#ffffff')>=4.5));\""}, {"t": "Focus Management in SPAs", "cat": "accessibility", "d": "SPA focus management: on route change, move focus to the main heading (announces the new page), modals trap and return focus, skip links at the top, and focus never drops to body after dialogs close. Without this, screen reader users don't know the page changed — the URL changed silently. Implement a route-change focus helper and use it everywhere. AI-generated SPAs almost always skip this — it's invisible to sighted mouse users and critical for everyone else.", "h": "Add focus-to-heading on every route change, verify modal focus trap + return, add skip links, test with a screen reader: navigate routes and confirm each announces, open/close dialogs and confirm focus returns.", "k": ["Route change → focus to main heading.", "Dialogs trap and return focus.", "Skip links bypass repetitive nav.", "Focus never lost to <body>."], "r": ["A route-change focus helper.", "Modal focus management.", "Screen reader verification."], "s": ["Page changes announced to screen readers.", "Focus always somewhere sensible."], "c": ["Focus management — w3.org/WAI/ARIA/apg", "SPA accessibility — web.dev"], "sig": "Signature rule: Signature route changes are tested with a screen reader — 'page changed silently' is a release blocker.", "demo": "// route-change focus helper\nfunction onRouteChange(headingId){\n  const h=document.getElementById?document.getElementById(headingId):null;\n  console.log(`route changed -> move focus to #${headingId}, set tabindex=-1 if needed`);\n  console.log('screen reader announces the new page title');\n}\nonRouteChange('page-title');"}, {"t": "Accessible Forms Deep Dive", "cat": "accessibility", "d": "Accessible forms: every input has a label (visible, not placeholder-only), related fields grouped in fieldset/legend, errors identified with aria-describedby and announced, required marked with aria-required AND visual indicator, instructions associated with the input. Multi-step forms announce progress. Placeholders are hints, not labels — they disappear. AI-generated forms fail here most: placeholder-only inputs are invisible to many users and unusable for all when filled.", "h": "Label every input visibly, group with fieldset/legend, wire errors via aria-describedby, mark required both visually and programmatically, test with a screen reader completing the form, then test error recovery (can the user find and fix errors?).", "k": ["Visible labels — placeholders are not labels.", "Errors linked and announced.", "fieldset/legend for groups.", "Required marked visually + programmatically."], "r": ["Label/fieldset markup.", "Error association.", "Screen reader form test."], "s": ["Form completable with screen reader alone.", "Errors findable and fixable."], "c": ["Forms — w3.org/WAI/tutorials/forms", "USWDS form guidance — designsystem.digital.gov"], "sig": "Signature rule: Signature forms are tested by completing them with a screen reader — including the error path.", "demo": "// accessible field markup\nfunction field(id,label,error,hint){\n  return `<div class=\"field\">\n  <label for=\"${id}\">${label}</label>\n  ${hint?`<p id=\"${id}-hint\">${hint}</p>`:''}\n  <input id=\"${id}\" ${hint?`aria-describedby=\"${id}-hint\"`:''} ${error?`aria-invalid=\"true\" aria-describedby=\"${id}-err\"`:''}>\n  ${error?`<p id=\"${id}-err\" role=\"alert\">${error}</p>`:''}\n</div>`;\n}\nconsole.log(field('email','Email address','Enter a valid email','We never share it.').split('\\n')[1]);"}, {"t": "Reduced Motion and Vestibular Safety", "cat": "accessibility", "d": "Vestibular disorders make animation physically sickening for some users: respect prefers-reduced-motion by disabling parallax, autoplay, and non-essential animation; never auto-play video with motion; provide a manual 'reduce motion' toggle too (some users don't set the OS flag). Essential motion (loading indicators) stays but simplified. AI-generated marketing sites love parallax hero animations — they're the exact thing that harms vestibular users.", "h": "Add the reduced-motion media query killing non-essential animation, remove parallax/autoplay-motion, add a manual reduce-motion toggle persisted per user, test with the OS flag on, then verify essential feedback still works without motion.", "k": ["prefers-reduced-motion disables parallax/autoplay/non-essential.", "Manual toggle too — not everyone sets the OS flag.", "Essential feedback works without motion.", "Auto-playing motion is opt-in, never default."], "r": ["The media query + a manual toggle.", "A vestibular-safe test (flag on).", "Non-motion feedback alternatives."], "s": ["No motion-induced harm possible.", "Content fully usable without animation."], "c": ["prefers-reduced-motion — developer.mozilla.org", "Vestibular — w3.org/WAI/WCAG21/Understanding/animation-from-interactions"], "sig": "Signature rule: Signature sites default embedded media to paused — motion starts by user choice.", "demo": "/* vestibular-safe motion */\n@media (prefers-reduced-motion: reduce){\n  *,*::before,*::after{\n    animation-duration:0.01ms !important;\n    transition-duration:0.01ms !important;\n    scroll-behavior:auto !important;\n  }\n  .parallax{transform:none !important;}\n}\nconsole.log('also: manual toggle -> html[data-motion=reduced] applies the same rules');"}, {"t": "Micro-interactions with Purpose", "cat": "interaction-patterns", "d": "Micro-interactions (button press feedback, toggle switches, like animations, progress indicators) confirm actions and teach the interface. Each has: trigger, rules, feedback, loops/modes. Keep them under 300ms, make them reversible-feeling, and never block input. The like-button burst is the canonical example — delightful, instant, honest. AI-generated UIs feel dead without micro-interactions and annoying with too many; one per action, purposeful.", "h": "Identify the key actions needing feedback, design one micro-interaction each (trigger→feedback), keep under 300ms and non-blocking, respect reduced-motion, then user-test: does it confirm the action or distract?", "k": ["One micro-interaction per action — confirm, don't decorate.", "Under 300ms, never blocks input.", "Trigger → rules → feedback.", "Reduced-motion gets instant state change instead."], "r": ["Motion tokens.", "A reduced-motion fallback.", "User feedback."], "s": ["Interactions never block input.", "Meaning preserved without animation."], "c": ["Microinteractions — microinteractions.com", "Animation UX — laws of UX"], "sig": "Signature rule: Signature micro-interactions have a no-motion equivalent that communicates the same state change.", "demo": "// toggle micro-interaction logic\nfunction toggle(el, on){\n  el.setAttribute('aria-checked',on);\n  el.classList.toggle('on',on);\n  // CSS: .toggle{transition:transform .18s ease-out} thumb slides\n  // reduced-motion: instant state change, same aria state\n  console.log(`toggle -> ${on} (visual: slide 180ms; reduced-motion: instant)`);\n}\ntoggle({setAttribute:()=>{},classList:{toggle:()=>{}}},true);"}, {"t": "Drag and Drop That Works", "cat": "interaction-patterns", "d": "Drag and drop needs: draggable affordance (handle), drop targets highlighted on dragover, keyboard alternative (move buttons or cut/paste), touch support (pointer events, not just mouse), and clear success feedback. The HTML5 DnD API is mouse-only — for real products use Pointer Events or a library (dnd-kit) with keyboard support built in. AI kanban boards and file uploads need this — and the keyboard alternative is non-negotiable, not nice-to-have.", "h": "Implement with pointer events (or dnd-kit), highlight valid drop targets, add keyboard move alternative, support touch, announce moves to screen readers, then test: mouse, keyboard-only, and touch completion.", "k": ["Pointer Events — not mouse-only.", "Keyboard alternative mandatory.", "Drop targets highlight on dragover.", "Announce moves to screen readers."], "r": ["dnd-kit or pointer-events implementation.", "Keyboard move controls.", "Touch testing."], "s": ["Full keyboard operability.", "Touch works."], "c": ["dnd-kit — dndkit.com", "DnD accessibility — w3.org/WAI/ARIA/apg/patterns"], "sig": "Signature rule: Signature drag operations always offer 'move to position N' keyboard controls — parity, not alternative-lite.", "demo": "// keyboard-accessible reorder\nfunction moveItem(list, from, to){\n  const item=list[from];\n  const next=list.filter((_,i)=>i!==from);\n  next.splice(to,0,item);\n  return next;\n}\nlet tasks=['write','review','ship'];\ntasks=moveItem(tasks,0,2);\nconsole.log('reordered:',tasks);\nconsole.log('keyboard: select item, press arrows, Enter to drop; announced via live region');"}, {"t": "Command Palettes (Cmd+K)", "cat": "interaction-patterns", "d": "Command palettes (Cmd+K) give power users keyboard access to everything: fuzzy search over commands, recent items first, keyboard navigation, and action execution without the mouse. Implementation: a global key listener, a fuzzy matcher over registered commands, grouped results, and footer hints. Register commands from features (each feature declares its commands). AI tools live in the palette — 'ask AI', 'generate', 'explain' as palette commands makes AI discoverable.", "h": "Build the palette shell (trigger, input, fuzzy list, footer), create a command registry features write to, rank recents first, add keyboard navigation, then register 20 real commands and test: can a keyboard user do everything?", "k": ["Fuzzy search over a command registry.", "Recents ranked first.", "Features register their own commands.", "Footer hints teach shortcuts."], "r": ["A fuzzy matcher.", "A command registry.", "Global key handling."], "s": ["Palette fully keyboard operable.", "Commands have visible shortcut hints."], "c": ["cmdk — cmdk.com", "Palette UX — linear.app (reference)"], "sig": "Signature rule: Signature palettes include AI commands in the default registry — AI actions are discoverable, not hidden.", "demo": "// fuzzy command matching\nconst commands=[\n  {id:'new-project',title:'New project',hint:'N'},\n  {id:'ask-ai',title:'Ask AI',hint:'A'},\n  {id:'toggle-theme',title:'Toggle theme',hint:'T'},\n];\nfunction fuzzy(q){\n  q=q.toLowerCase();\n  return commands.filter(c=>{\n    let i=0;const t=c.title.toLowerCase();\n    for(const ch of q){i=t.indexOf(ch,i);if(i<0)return false;i++;}\n    return true;\n  });\n}\nconsole.log(fuzzy('ask').map(c=>c.title));\nconsole.log('Cmd+K -> type -> arrows -> Enter');"}, {"t": "Infinite Scroll vs Pagination", "cat": "interaction-patterns", "d": "Infinite scroll suits discovery (feeds, galleries); pagination suits goal-directed tasks (search results, admin tables, anything with a footer). Infinite scroll needs: a sentinel observer, loading indicator, 'back to top', and — critically — a way to reach the footer (or no footer dependency). It breaks the back button unless scroll position restores. Choose deliberately: if users need to find item #47 again, paginate. AI content feeds default to infinite scroll; AI admin tools must paginate.", "h": "Decide per view (discovery vs goal-directed), implement with IntersectionObserver sentinel, preserve scroll position on back-navigation, ensure footer reachability, add keyboard access to all loaded items, then test: find an item, navigate away, come back.", "k": ["Discovery → infinite scroll; goals → pagination.", "Sentinel observer triggers loads.", "Back button restores position.", "Footer must stay reachable."], "r": ["IntersectionObserver.", "Scroll restoration.", "A footer strategy."], "s": ["Keyboard reaches all loaded content.", "Screen readers notified of new content."], "c": ["Infinite scroll — web.dev", "Pagination UX — nngroup.com/articles/infinite-scrolling"], "sig": "Signature rule: Signature infinite lists offer a 'switch to pages' control — user choice, not designer fiat.", "demo": "// infinite scroll sentinel\nlet page=0,loading=false,done=false;\nfunction onSentinelVisible(){\n  if(loading||done)return;\n  loading=true;\n  console.log('loading page',page+1+'…');\n  setTimeout(()=>{page++;loading=false;if(page>=5)done=true;\n    console.log('page',page,'loaded'+(done?' (end reached)':''));},200);\n}\nonSentinelVisible();\nconsole.log('IntersectionObserver on sentinel div triggers loads; footer link duplicated above feed');"}, {"t": "Undo Patterns in UI", "cat": "interaction-patterns", "d": "UI undo patterns: immediate undo toast ('Deleted — Undo', 5-10s) for destructive actions beats confirmation dialogs — users act fast and recover easily. Confirmations are for irreversible, high-stakes actions only (permanent delete of shared data). Archive beats delete (recoverable by design). The toast needs: the action description, the Undo button, keyboard focusability, and enough time. AI destructive actions (bulk deletes, overwrites) must offer undo — generated actions feel unsafe without it.", "h": "Replace confirmation dialogs with undo toasts for reversible destructives, keep confirmations only for irreversible high-stakes, implement the toast with focusable Undo and 8s timeout, test: delete, undo within window, verify restore; delete, wait, verify gone.", "k": ["Undo toast beats confirmation for reversible actions.", "Confirmations only for irreversible high-stakes.", "Toast: description + Undo + 8s + focusable.", "Archive > delete where possible."], "r": ["A toast system with actions.", "Undoable command implementations.", "An archive alternative."], "s": ["Undo keyboard reachable.", "Irreversible actions clearly marked."], "c": ["Undo — nngroup.com/articles/confirmation-dialog", "Material snackbar — material.io"], "sig": "Signature rule: Signature deletes are soft for 30 days — 'permanent' means after the grace period, with notice.", "demo": "// undo toast pattern\nconst trash=[];\nfunction remove(item){\n  const idx=items.indexOf(item); items.splice(idx,1);\n  console.log(`toast: \"Removed ${item}\" [Undo] (8s)`);\n  const timer=setTimeout(()=>console.log(item,'permanently gone'),8000);\n  return {undo(){clearTimeout(timer);items.splice(idx,0,item);console.log('restored:',item);}};\n}\nlet items=['a','b','c'];\nconst op=remove('b');\nop.undo();\nconsole.log('items:',items);"}, {"t": "Progressive Disclosure", "cat": "interaction-patterns", "d": "Progressive disclosure shows the essential now and reveals the advanced on demand: 'Show more', advanced settings sections, expandable rows. It fights the #1 UI sin — overwhelming users with everything at once. Rules: the default view handles 80% of tasks, disclosure controls are clearly labeled, state persists (don't collapse what the user opened), and nothing critical hides behind disclosure. AI settings panels and complex tools need this — power without intimidation.", "h": "Identify the 80% path per view, move the rest behind labeled disclosure, persist open/closed state, ensure nothing critical is hidden, then test with new users: can they complete the main task without opening anything?", "k": ["Default view handles 80% of tasks.", "Disclosure clearly labeled.", "State persists — don't re-collapse.", "Nothing critical hidden."], "r": ["Disclosure components.", "State persistence.", "New-user testing."], "s": ["Disclosed content keyboard reachable.", "State announced to screen readers."], "c": ["Progressive disclosure — nngroup.com/articles/progressive-disclosure", "Interaction design — laws of UX"], "sig": "Signature rule: Signature disclosure controls state what they reveal — 'Show 12 advanced settings', not 'Show more'.", "demo": "// progressive disclosure\nconst settings={basic:['name','email'],advanced:['webhook_url','api_rate','custom_css','sso','audit_log','retention','ip_allowlist','cors','backup_schedule','log_level','feature_flags','sandbox']};\nfunction render(showAdvanced){\n  let h='Basic: '+settings.basic.join(', ');\n  h+=`\\n<button>Show ${settings.advanced.length} advanced settings</button>`;\n  if(showAdvanced)h+='\\nAdvanced: '+settings.advanced.join(', ');\n  return h;\n}\nconsole.log(render(false));"}, {"t": "Paper Prototyping to Clickable", "cat": "prototyping", "d": "Prototyping ladder: paper sketches (fastest, test concepts) → wireframes (structure, no styling) → clickable mockups (Figma, test flows) → coded prototype (test real interactions). Match fidelity to the question: testing navigation needs clickable; testing visual design needs high fidelity. Test with 5 users per round, fix, repeat — each round cheaper than building wrong. AI UI generation compresses this: generate the clickable prototype directly, then test it like any prototype.", "h": "Sketch the concept on paper, build the clickable version at the fidelity matching your question, test with 5 users, fix the top issues, repeat until no new issues, then hand the validated prototype to build.", "k": ["Fidelity matches the question being tested.", "5 users per round find most issues.", "Prototype the flow, not the pixels (early).", "AI generates the clickable version directly."], "r": ["A prototyping tool (Figma/code).", "5 test users per round.", "A test script."], "s": ["Prototypes testable by keyboard.", "Test with diverse users."], "c": ["Prototyping — nngroup.com/articles/ux-prototype-hi-fi", "Figma prototyping — help.figma.com"], "sig": "Signature rule: Signature prototypes include the error and empty states — prototypes that only show happy paths lie.", "demo": "node -e \"\nconst ladder=[\n  ['paper sketch','concept: does the idea make sense?'],\n  ['wireframe','structure: can users find things?'],\n  ['clickable','flow: can users complete tasks?'],\n  ['coded','interaction: does it feel right?']\n];\nladder.forEach(([f,q],i)=>console.log((i+1)+'. '+f+' -> '+q));\nconsole.log('5 users per round; fix top issues; repeat');\""}, {"t": "Usability Testing on a Budget", "cat": "prototyping", "d": "Budget usability testing: 5 users, 3-5 tasks, think-aloud protocol, 30 minutes each — finds ~85% of issues. Recruit from your actual user base (not coworkers), give tasks not instructions ('buy a blue shirt' not 'click the shop tab'), don't help, note where they struggle. Synthesize: top 3 issues, fix, retest. AI-generated UIs need this desperately — the AI can't watch a confused user. One round before every major release.", "h": "Write 3-5 realistic tasks, recruit 5 real users, run think-aloud sessions without helping, synthesize the top 3 issues, fix them, retest with 5 new users, then track: do the same issues recur?", "k": ["5 users find ~85% of issues.", "Tasks, not instructions.", "Don't help — note struggles.", "Fix top 3, retest."], "r": ["5 representative users.", "Task scenarios.", "A note-taker."], "s": ["Test with users with disabilities included.", "Consent and privacy for recordings."], "c": ["Usability testing — nngroup.com/articles/how-to-conduct-usability-study", "Think aloud — nngroup.com/articles/thinking-aloud"], "sig": "Signature rule: Signature usability rounds include one assistive-tech user — if it doesn't work for them, it doesn't ship.", "demo": "node -e \"\nconst plan={\n  users:5, minutes:30,\n  tasks:['Sign up','Find pricing','Start a project','Invite a teammate'],\n  protocol:'think aloud, no helping',\n  output:'top 3 issues -> fix -> retest with 5 new users'\n};\nconsole.log(JSON.stringify(plan,null,1));\""}, {"t": "A/B Testing Without Lying to Yourself", "cat": "prototyping", "d": "Honest A/B testing: one variable at a time, a pre-registered hypothesis and success metric, enough sample size for statistical significance (use a calculator, not gut feel), run for full weekly cycles (weekday/weekend behavior differs), and segment results (new vs returning). Don't peek early and stop at the first positive — that's p-hacking. AI-generated variants make testing cheap; the discipline is what makes it truthful.", "h": "Write the hypothesis and metric before starting, calculate required sample size, run full weekly cycles without peeking, segment by user type, then decide: ship, iterate, or discard — and document why.", "k": ["Hypothesis + metric registered BEFORE the test.", "Sample size from a calculator.", "Full weekly cycles; no peeking.", "Segment: new vs returning differ."], "r": ["A testing framework.", "A significance calculator.", "Segmentation."], "s": ["No dark patterns tested as 'wins'.", "Losing variants documented too."], "c": ["A/B testing — optimizely.com/optimization-glossary/ab-testing", "Statistics — evanmiller.org/ab-testing"], "sig": "Signature rule: Signature A/B tests pre-register a harm metric — a variant that wins revenue but hurts trust loses.", "demo": "node -e \"\n// sample size intuition (simplified)\nfunction needed(baseline, mde){\n  // rough: detect relative lift with 80% power, 95% confidence\n  const p=baseline, d=baseline*mde;\n  const n=Math.ceil(16*p*(1-p)/(d*d));\n  return n;\n}\nconsole.log('baseline 10%, detect 20% lift -> ~'+needed(0.10,0.20).toLocaleString()+' per variant');\nconsole.log('rule: calculate BEFORE, run full weeks, no peeking');\""}, {"t": "Design Critique Format", "cat": "prototyping", "d": "Useful design critiques: presenter states the goal and what feedback they want (not a tour), critics ask clarifying questions first, then give specific, actionable feedback tied to the goal ('the primary action is unclear because...' not 'I don't like blue'), and the presenter doesn't defend — they take notes. End with next steps. AI-generated designs get critiqued the same way — the format works regardless of who (or what) made the mockup.", "h": "Set the format (goal → questions → feedback → next steps), require feedback tied to goals with specifics, ban defense during critique, rotate the facilitator, then review: did critiques change the design measurably?", "k": ["Goal first — feedback serves the goal.", "Questions before opinions.", "Specific and actionable, not taste.", "No defending during critique."], "r": ["A critique format doc.", "A facilitator rotation.", "Goal statements per design."], "s": ["Critique the work, never the person.", "Diverse critics catch diverse issues."], "c": ["Design critique — designbetter.co", "Critique method — nngroup.com"], "sig": "Signature rule: Signature critiques start with what's working — critique builds on strengths, not just fixes weaknesses.", "demo": "node -e \"\nconst format=['1. presenter: goal + what feedback is wanted (2 min)',\n '2. critics: clarifying questions (5 min)',\n '3. feedback: specific, tied to goal (15 min)',\n '4. next steps: owner + date'];\nformat.forEach(f=>console.log(f));\nconsole.log('rule: no defending during critique; take notes');\""}, {"t": "Handoff: Design to Build", "cat": "prototyping", "d": "Design-to-build handoff: the design is the spec — redlines (spacing, type, color as tokens), all states (default/hover/focus/disabled/loading/error/empty), responsive behavior, motion specs (duration/easing), and edge cases (long names, empty lists, errors). Build from tokens and components, not pixel measurements. The handoff meeting walks through states and edge cases, not the happy path. AI builders consume handoff specs directly — structured specs beat annotated screenshots.", "h": "Produce the handoff package (tokens, components, all states, responsive + motion specs, edge cases), walk through states and edge cases together, build from the system (not measurements), then compare build to design state-by-state.", "k": ["All states specified, not just happy path.", "Tokens and components, not pixel measurements.", "Edge cases: long text, empty, error.", "Walkthrough covers states, not the tour."], "r": ["A handoff template.", "Token/component parity.", "State coverage checklist."], "s": ["Handoff includes accessibility annotations.", "Focus order specified."], "c": ["Handoff — zeplin.io", "Design specs — figma.com/dev-mode"], "sig": "Signature rule: Signature handoffs are checked against the built result state-by-state — drift is caught, not discovered.", "demo": "node -e \"\nconst handoff={component:'SearchField',states:['default','focus','typing','loading','results','no-results','error'],tokens:['color.border','space.2','radius.md'],motion:{duration:180,easing:'ease-out'},edge:['300-char query','no JS']};\nconst missing=handoff.states.filter(s=>!s);\nconsole.log('states:',handoff.states.length,'tokens: 3, motion: spec\\'d, edge cases:',handoff.edge.length);\nconsole.log('build verified state-by-state against this spec');\""}];
function ladderTier(r){return r<=2?"Foundations":(r<=4?"Compounded":"Advanced");}
function generate(seed,opts){
  opts=opts||{};
  var n=DATA.length;
  var e=DATA[(seed-1)%n];
  var cycle=Math.floor((seed-1)/n);
  var ladder=1+Math.floor((((seed-1)%n)/7));
  var rec={
    id:PREFIX+String(seed).padStart(6,'0'),
    name:e.t,
    title:DBTITLE+': '+e.t+(cycle>0?' (variant '+cycle+')':''),
    description:SRC==='signature'?('Signature treatment: '+e.sig+' '+e.d):e.d,
    category:e.cat,
    ladder_rank:ladder,
    ladder_tier:ladderTier(ladder),
    how_it_works:e.h,
    key_points:e.k,
    requirements:e.r,
    standards:e.s,
    citations:e.c,
    src:SRC,
    src_detail:SRC_DETAIL,
    seed:seed
  };
  if(SRC==='signature'){rec.signature_treatment=e.sig;}
  rec.demo={program:e.demo};
  if(opts.category&&rec.category!==opts.category){/* category filter honored at query layer */}
  return rec;
}
function escRx(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function validate(r){
  var errs=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  if(!new RegExp('^'+escRx(PREFIX)+'\\d{6}$').test(r.id||''))errs.push('id');
  if(typeof r.title!=='string'||r.title.indexOf(DBTITLE)!==0)errs.push('title');
  if(CATS.indexOf(r.category)<0)errs.push('category');
  if(!(r.ladder_rank>=1&&r.ladder_rank<=5))errs.push('ladder_rank');
  if(['Foundations','Compounded','Advanced'].indexOf(r.ladder_tier)<0)errs.push('ladder_tier');
  if(r.src!==SRC)errs.push('src');
  if(typeof r.description!=='string'||r.description.length<200)errs.push('description');
  REQUIRED.forEach(function(k){if(r[k]===undefined||r[k]===null)errs.push('missing:'+k);});
  if(!Array.isArray(r.key_points)||r.key_points.length<3)errs.push('key_points');
  if(!r.demo||typeof r.demo.program!=='string'||!r.demo.program.length)errs.push('demo');
  return {ok:errs.length===0,errors:errs};
}
function driftCheck(rec,sample){
  var dups=(sample||[]).filter(function(x){return x&&x.title===rec.title&&x.category===rec.category;});
  return dups.length?{ok:false,errors:['duplicate title+category already in archive']}:{ok:true,errors:[]};
}
var api={generate:generate,validate:validate,driftCheck:driftCheck,slug:"ai-toolmaking-ui-ux-design",version:"jahdb-ai-toolmaking-ui-ux-design-1.0"};
if(typeof module!=='undefined'&&module.exports)module.exports=api;
if(typeof window!=='undefined'){
  window["jahdb_ai_toolmaking_ui_ux_design"]=api;
  try{if(window.JAHDB&&JAHDB.registerGenerator)JAHDB.registerGenerator("ai-toolmaking-ui-ux-design",api);}catch(e){}
}
})();
